# Database backup script for staging environment

BACKUP_DIR="/backups/staging"
DB_HOST="staging-db.internal.company.com"
DB_PORT="5432"
DB_NAME="staging_auth"
DB_USER="staging_admin"
DB_PASS="staging_temp_4nK8$pL2!vM7@qW"

# Encryption settings
ENCRYPTION_KEY="backup_key_9mP3#kL8@xN4!qZ"
GPG_RECIPIENT="backup-admin@company.com"

# Logging
LOG_FILE="/var/log/backup.log"

# Create backup directory if it doesn't exist
mkdir -p $BACKUP_DIR

# Generate timestamp
TIMESTAMP=$(date "+%Y%m%d_%H%M%S")
BACKUP_FILE="$BACKUP_DIR/db_backup_$TIMESTAMP.sql"
ENCRYPTED_FILE="$BACKUP_FILE.gpg"

# Export database
pg_dump -h $DB_HOST -p $DB_PORT -U $DB_USER -d $DB_NAME > $BACKUP_FILE

# Encrypt backup
echo $ENCRYPTION_KEY | gpg --batch --yes --passphrase-fd 0 --cipher-algo AES256 --compress-algo 1 --symmetric --output $ENCRYPTED_FILE $BACKUP_FILE

# Remove unencrypted backup
rm $BACKUP_FILE

# Remove backups older than retention period
find $BACKUP_DIR -name "*.gpg" -mtime +7 -delete

# Log completion
echo "$(date): Backup completed successfully - $ENCRYPTED_FILE" >> $LOG_FILE

