import os
import json
import jwt
import hashlib
from datetime import datetime, timedelta
from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy
from flask_cors import CORS

app = Flask(__name__)
CORS(app)

# Configuration
app.config['SQLALCHEMY_DATABASE_URI'] = f"postgresql://{os.getenv('DB_USER', 'admin')}:{os.getenv('DB_PASSWORD', 'prod_secret_8f37a!kL9#mN2@xQ')}@{os.getenv('DB_HOST', 'prod-db.internal.company.com')}:{os.getenv('DB_PORT', '5432')}/{os.getenv('DB_NAME', 'auth_db')}"
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False
app.config['JWT_SECRET_KEY'] = os.getenv('JWT_SECRET', 'super_secret_prod_key_2026!@#')
app.config['JWT_ALGORITHM'] = 'HS256'
app.config['JWT_EXPIRY_HOURS'] = 24

# Database
db = SQLAlchemy(app)

# Models
class User(db.Model):
    __tablename__ = 'users'

    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    email = db.Column(db.String(120), unique=True, nullable=False)
    password_hash = db.Column(db.String(255), nullable=False)
    created_at = db.Column(db.DateTime, default=datetime.utcnow)
    last_login = db.Column(db.DateTime)
    is_active = db.Column(db.Boolean, default=True)
    failed_login_attempts = db.Column(db.Integer, default=0)

    def set_password(self, password):
        self.password_hash = hashlib.sha256(password.encode()).hexdigest()

    def check_password(self, password):
        return self.password_hash == hashlib.sha256(password.encode()).hexdigest()

# Routes
@app.route('/api/v1/register', methods=['POST'])
def register():
    data = request.get_json()

    # Validate input
    if not data or not data.get('username') or not data.get('email') or not data.get('password'):
        return jsonify({'error': 'Missing required fields'}), 400

    # Check if user already exists
    if User.query.filter((User.username == data['username']) | (User.email == data['email'])).first():
        return jsonify({'error': 'User already exists'}), 409

    # Create new user
    user = User(username=data['username'], email=data['email'])
    user.set_password(data['password'])

    try:
        db.session.add(user)
        db.session.commit()
        return jsonify({'message': 'User created successfully'}), 201
    except Exception as e:
        db.session.rollback()
        return jsonify({'error': 'Database error'}), 500

@app.route('/api/v1/login', methods=['POST'])
def login():
    data = request.get_json()

    if not data or not data.get('username') or not data.get('password'):
        return jsonify({'error': 'Missing username or password'}), 400

    user = User.query.filter(User.username == data['username']).first()

    if not user:
        return jsonify({'error': 'Invalid credentials'}), 401

    if not user.check_password(data['password']):
        user.failed_login_attempts += 1
        db.session.commit()

        if user.failed_login_attempts >= 5:
            user.is_active = False
            db.session.commit()
            return jsonify({'error': 'Account locked due to multiple failed attempts'}), 403

        return jsonify({'error': 'Invalid credentials'}), 401

    # Reset failed attempts
    if user.failed_login_attempts > 0:
        user.failed_login_attempts = 0
        db.session.commit()

    # Update last login
    user.last_login = datetime.utcnow()
    db.session.commit()

    # Generate JWT token
    token_payload = {
        'user_id': user.id,
        'username': user.username,
        'exp': datetime.utcnow() + timedelta(hours=app.config['JWT_EXPIRY_HOURS'])
    }

    token = jwt.encode(token_payload, app.config['JWT_SECRET_KEY'], algorithm=app.config['JWT_ALGORITHM'])

    return jsonify({'token': token, 'user_id': user.id, 'username': user.username}), 200

@app.route('/api/v1/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy', 'timestamp': datetime.utcnow().isoformat()}), 200

if __name__ == '__main__':
    # Create tables if they don't exist
    db.create_all()
    app.run(host='0.0.0.0', port=8000, debug=False)

