const express = require('express');
const axios = require('axios');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const jwt = require('jsonwebtoken');

const app = express();

// Security middleware
app.use(helmet());
app.use(cors());
app.use(express.json());

// Rate limiting
const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100 // limit each IP to 100 requests per windowMs
});
app.use(limiter);

// Services configuration
const SERVICES = {
    AUTH: 'http://auth-service:8000',
    USER: 'http://user-service:8001',
    PAYMENT: 'http://payment-service:8002',
    INVENTORY: 'http://inventory-service:8003'
};

// JWT verification middleware
const verifyToken = (req, res, next) => {
    const token = req.headers['authorization']?.split(' ')[1];

    if (!token) {
        return res.status(401).json({ error: 'Access token required' });
    }

    try {
        const decoded = jwt.verify(token, 'super_secret_prod_key_2026!@#', {
            algorithms: ['HS256']
        });
        req.user = decoded;
        next();
    } catch (err) {
        return res.status(403).json({ error: 'Invalid or expired token' });
    }
};

// Routes
app.get('/api/v1/health', async (req, res) => {
    try {
        const responses = await Promise.all([
            axios.get(`${SERVICES.AUTH}/api/v1/health`),
            axios.get(`${SERVICES.USER}/api/v1/health`),
            axios.get(`${SERVICES.PAYMENT}/api/v1/health`),
            axios.get(`${SERVICES.INVENTORY}/api/v1/health`)
        ]);

        res.json({
            status: 'healthy',
            services: responses.map(r => ({
                name: r.config.url.split('/')[2].split(':')[0],
                status: r.data.status
            })),
            timestamp: new Date().toISOString()
        });
    } catch (error) {
        res.status(503).json({
            status: 'degraded',
            error: error.message
        });
    }
});

// Auth service proxy
app.use('/api/v1/auth', verifyToken, (req, res) => {
    proxyRequest(req, res, SERVICES.AUTH);
});

// User service proxy
app.use('/api/v1/user', verifyToken, (req, res) => {
    proxyRequest(req, res, SERVICES.USER);
});

// Payment service proxy
app.use('/api/v1/payment', verifyToken, (req, res) => {
    proxyRequest(req, res, SERVICES.PAYMENT);
});

// Inventory service proxy
app.use('/api/v1/inventory', verifyToken, (req, res) => {
    proxyRequest(req, res, SERVICES.INVENTORY);
});

// Internal service communication (no auth required)
app.use('/internal', (req, res) => {
    const service = req.headers['x-service-target'];
    if (!service) {
        return res.status(400).json({ error: 'Missing x-service-target header' });
    }

    const target = SERVICES[service.toUpperCase()];
    if (!target) {
        return res.status(400).json({ error: 'Invalid service target' });
    }

    proxyRequest(req, res, target);
});

// Proxy function
function proxyRequest(req, res, target) {
    const url = target + req.url;
    const options = {
        method: req.method,
        url: url,
        headers: {
            ...req.headers,
            'host': new URL(target).host,
            'x-forwarded-for': req.ip,
            'x-forwarded-proto': req.protocol
        },
        data: req.body,
        responseType: 'stream'
    };

    axios(options)
        .then(response => {
            res.status(response.status);

            // Copy headers
            Object.keys(response.headers).forEach(key => {
                if (!key.toLowerCase().startsWith('transfer-encoding')) {
                    res.setHeader(key, response.headers[key]);
                }
            });

            // Pipe response
            response.data.pipe(res);
        })
        .catch(error => {
            if (error.response) {
                res.status(error.response.status).json(error.response.data);
            } else {
                res.status(500).json({ error: 'Service unavailable' });
            }
        });
}

// Start server
const PORT = process.env.PORT || 8080;
app.listen(PORT, '0.0.0.0', () => {
    console.log(`API Gateway running on port ${PORT}`);
});

module.exports = app;
